effect.shader:

 vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
 mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
 vec2 l2s( vec2 v ) { return (vec4(v,0.,1.0)*acLayerToScreen).xy; }
 #define fragCoord gl_FragCoord.xy

/////////////////////////

      // #define BLUR
      const ivec2 samples = ivec2(3,3);
      // const vec2 z = vec2(1,8);
      // const float complexity =8.0;
      // const float density = .6; // 0-1
      // const float sceneswitchspeed = .3;

      vec4 hash42(vec2 p)
      {
      	vec4 p4 = fract(vec4(p.xyxy) * vec4(.1031, .1030, .0973, .1099));
          p4 += dot(p4, p4.wzxy+33.33);
          return fract((p4.xxyz+p4.yzzw)*p4.zywx);
      }

      #define q(x,p) (floor((x)/(p))*(p))

      vec4 tex(vec2 C) {

          vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
          float iTime = autop? PROGRESS + (acTime*SPEED) : PROGRESS;

          vec2 R = iResolution.xy;
              vec4 o2 = vec4(1);

              vec2 uv = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
              uv.y *=acLayerSize.y/acLayerSize.x;
              // vec2 uv = acScreenNorm.st;
              uv /= scale;
              uv *= rot2m((0.0+angle)*0.0174533);
              uv += vec2((-250.0+position.x), (250.0+position.y))*vec2(-1.,1.0)/500.0;
              vec2 scaleVec;
              scaleVec = vec2(scale*stretch.x,scale*stretch.y);
              uv /= scaleVec;

              float t = iTime;
              t+=1e2;
              vec4 h = hash42(floor(uv) + floor(1.0*sceneswitchspeed));
              // vec4 h = hash42(floor(uv) + floor(t*sceneswitchspeed));
              uv.y += uv.x*(h.x-.5);
              uv.x *= R.x/R.y;
              uv *= z;
              uv += floor(t*sceneswitchspeed)*z*h.y; // adding *h.y so vertical seams are not always in the same place
              float s = 1.0;

              for (float i = 1.0;i <= complexity; ++ i) {
                  vec2 c = floor(uv+i);
                  vec4 h = hash42(c);
                  vec2 p = fract(uv+i+q(t,h.z+1.0)*h.y);
                  uv+= p*h.z*h.xy*vec2(s,2.0);
                  s = -s*(1.1+h.y);
                  if (h.w > density) {
                      o2 *= h;
                  }
              }
          o2 = step(.5,o2);
          return o2;
      }

/////////////////////////
 void main ()
 {

     vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
     vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

     vec2 image_size = getTexSize(inputImg.size);
     vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
     vec3 iMouse = vec3(0.5, 0.5, 0.5);
     float iTime = autop? PROGRESS + (acTime*SPEED) : PROGRESS;

     vec2 umefx;
     // umefx = acScreenNorm; 
     umefx = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
     umefx.y*=acLayerSize.y/acLayerSize.x;

     umefx /= scale;
     umefx *= rot2m((0.0+angle)*0.0174533);
     umefx += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.,1.0)/500.0;
     vec2 scaleVec;
     scaleVec = vec2(scale*stretch.x,scale*stretch.y);
     umefx /= scaleVec;

     /////////////////////////

 	vec4 o;

          vec2 R = iResolution.xy;
          vec2 C = fragCoord;
          // vec2 uv = acScreenNorm.st;
          vec2 uv = umefx;

              vec4 o2 = vec4(1.0);
              // vec2 uv = C/R.xy;
              vec2 N = uv- 0.5;
      // #ifdef BLUR
          if(EBLUR) {
          o = vec4(0.0);
          float accum = 0.0;

          for (int x = -samples.x; x < samples.x; ++x) {
              vec2 offset = vec2(x,0);
              float weight = abs(float(samples.x) - float(x));
              o += tex(C + offset) * weight;
              accum += weight;
          }
          for (int y = -samples.y; y < samples.y; ++y) {
              vec2 offset = vec2(0, y);
              float weight = abs(float(samples.y) - float(y));
              o += tex(C + offset) * weight;
              accum += weight;
          }
          o /= accum;
          }
      // #else
          // if(EBLUR) { 
          o = tex(C); 
          // }
      // #endif

          o=smoothstep(.2,.8,o) * mod(C.x,3.0)/2.5;
          o=clamp(o,0.,1.0);
        	o = pow(o,o-o+.5);

 	    vec4 factor = mix(texColorX,o,1.0);
 	    // const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
         // float luminance = dot(fragColor.rgb, luminanceWeighting);
         // vec4 gradmap = mix(color1,color2,luminance)*fragColor.a;
 	    // if(GRADMAP) { factor = mix(texColorX,gradmap,1.0); }

 	    // vec4 xbuffer = texture2DCv(buff1.texture, acScreenNorm.st);

     vec4 resultfinal;
       if( blendMode==0 ) { resultfinal = (factor * hardness) * texColor.a; }
       else if( blendMode==1 ) { factor *= hardness;
         vec4 c = factor + vec4(1.0)*(1.-factor.a);
         resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
         // resultfinal = min(factor, texColor) * texColor.a; }
       else if( blendMode==2 ) { factor *= hardness; 
         resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; }
           // resultfinal = max(factor, texColor) * texColor.a; }
       else if( blendMode==3 ) { factor *= hardness; resultfinal = (newLayer(texColor, factor) * hardness) * texColor.a; }

 	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
 	// }
 }
